package com.hostelcare.repository; import com.hostelcare.entity.ComplaintHistory; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface ComplaintHistoryRepository extends JpaRepository<ComplaintHistory,Long> { List<ComplaintHistory> findByComplaintComplaintIdOrderByChangedAtAsc(Long id); @org.springframework.data.jpa.repository.Query(value="SELECT AVG(TIMESTAMPDIFF(HOUR, c.created_at, h.changed_at)) FROM complaints c JOIN complaint_history h ON h.complaint_id=c.complaint_id WHERE h.new_status='RESOLVED'",nativeQuery=true) Double averageResolutionHours(); }
